insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_137'
from (values
('127.888.d.1.A',3,'At a career night, Noor lists airframe mechanic, composite technician and starting her own sheet metal shop as options. She is:','["identifying and comparing employment opportunities, including entrepreneurship", "naming no jobs", "avoiding work", "ignoring careers"]'::jsonb,0,'Career paths.','original'),
('127.888.d.1.A',4,'A person who starts a small business repairing aircraft skins is acting as:','["an air traffic controller", "an entrepreneur", "a ticket agent", "a flight attendant"]'::jsonb,1,'Entrepreneur.','original'),
('127.888.d.1.B',3,'During a rivet job, Tariq holds the bucking bar steady for his partner and calls out when the rivet is set. He is demonstrating how to:','["work alone", "avoid the task", "contribute and collaborate as an effective member of a team", "slow others down"]'::jsonb,2,'Team roles.','original'),
('127.888.d.1.B',4,'Two-person riveting depends on teamwork because the:','["shooter works alone", "rivet sets itself", "bucker can leave", "shooter and bucker must coordinate for a good rivet"]'::jsonb,3,'Coordinated crew.','original'),
('127.888.d.1.C',3,'A student is told that a mechanic must never sign for a repair that was done wrong, even if a deadline is close. She is identifying:','["individual ethical and legal behavior standards according to professional and industry standards", "no standards", "optional rules", "shop slang"]'::jsonb,0,'Professional standards.','original'),
('127.888.d.1.C',4,'A mechanic''s signature on a repair certifies that:','["the work is fast", "the work meets the required standards", "the work is cheap", "the work is pretty"]'::jsonb,1,'Signature meaning.','original'),
('127.888.d.1.D',3,'A class reads why mechanics must be able to read, speak and write English to follow aviation manuals and records. They are researching:','["a local custom", "no requirement", "the impact of English language proficiency requirements on aviation", "a style choice"]'::jsonb,2,'English in aviation.','original'),
('127.888.d.1.D',4,'Misreading a manual step because of a language barrier could lead to:','["a faster repair", "a free repair", "a perfect repair", "a repair done incorrectly"]'::jsonb,3,'Language risk.','original'),
('127.888.d.1.E',3,'A hangar safety talk covers lack of knowledge, complacency, pressure and fatigue as common causes of maintenance errors. They are identifying:','["human factors that may impact health and safety in a workplace", "weather factors only", "no factors", "tool brands"]'::jsonb,0,'Human factors.','original'),
('127.888.d.1.E',4,'Complacency in a hangar means a worker:','["is training", "becomes too comfortable and overlooks risks", "is extra careful", "is on break"]'::jsonb,1,'Complacency.','original'),
('127.888.d.1.F',3,'A shop requires a second mechanic to inspect control cable work, because people make mistakes. This explains:','["paint issues", "tool failure", "the role of human factors in maintaining health and safety in the workplace", "no role"]'::jsonb,2,'Human factor controls.','original'),
('127.888.d.1.F',4,'A duplicate inspection of critical work reduces the chance that:','["work slows to nothing", "safety improves", "errors are found", "one person''s error goes unnoticed"]'::jsonb,3,'Duplicate inspection.','original'),
('127.888.d.1.G',3,'A mechanic refuses to sign off a repair she hasn''t fully checked, even when her supervisor pushes. This shows how:','["an employee''s personal responsibility affects health and safety", "rules are flexible", "pressure removes responsibility", "safety is optional"]'::jsonb,0,'Personal responsibility.','original'),
('127.888.d.1.G',4,'Taking a shortcut because ''nobody will check'' shows:','["extra safety", "poor personal responsibility", "good judgment", "teamwork"]'::jsonb,1,'Own your work.','original'),
('127.888.d.1.H',3,'In a role-play, a lead asks a student to use an uncertified bolt to save time. She declines and reports it. She is applying:','["avoidance", "rule breaking", "reasoning skills to make ethical decisions in simulated workplace situations", "poor judgment"]'::jsonb,2,'Ethical reasoning.','original'),
('127.888.d.1.H',4,'Using a part that is not approved for an aircraft is:','["acceptable", "a shortcut", "a bargain", "a safety and legal violation"]'::jsonb,3,'Approved parts.','original'),
('127.888.d.1.I',3,'A shop rule says no dangling jewelry, tied-back hair and safety footwear when working around machinery. These are examples of:','["industry standards related to employee appearance and health habits", "decor", "optional style", "random rules"]'::jsonb,0,'Appearance standards.','original'),
('127.888.d.1.I',4,'Good sleep and nutrition are listed in many safety programs because they help a technician:','["miss work", "stay alert and avoid errors", "work slowly", "ignore details"]'::jsonb,1,'Health habits.','original'),
('127.888.d.1.J',3,'Dani writes a short, clear note in the logbook and then briefs the next shift in person. She is practicing:','["unclear notes", "no communication", "effective written and oral communication skills", "mumbling"]'::jsonb,2,'Written and oral.','original'),
('127.888.d.1.J',4,'A shift handoff note should include:','["only a name", "nothing", "only the date", "the work done, work remaining and any hazards"]'::jsonb,3,'Handoff content.','original'),
('127.888.d.1.K',3,'A supervisor explains a job, and the mechanic repeats the steps back to confirm them. This is an example of:','["effective listening skills", "poor listening", "interrupting", "ignoring"]'::jsonb,0,'Listening.','original'),
('127.888.d.1.K',4,'Repeating instructions back to the speaker helps ensure:','["it is forgotten", "the message was understood correctly", "it is changed", "it is ignored"]'::jsonb,1,'Read-back.','original'),
('127.888.d.1.L',3,'A mechanic learns that ''shall'' in a regulation means something must be done, while ''may'' means it is optional. She is applying:','["random terms", "slang", "FAA standard terms that have specific expectations for performance", "casual words"]'::jsonb,2,'FAA terms.','original'),
('127.888.d.1.L',4,'In FAA regulations, the word ''shall'' indicates:','["a suggestion", "an optional step", "a hint", "a mandatory requirement"]'::jsonb,3,'Shall is mandatory.','original'),
('127.888.d.2.A',3,'Before riveting, a student puts on eye and ear protection and keeps loose clothing away from the rivet gun. She is describing:','["best practices for maintenance safety, including the use of personal protective equipment", "skipping rules", "no PPE", "unsafe habits"]'::jsonb,0,'Maintenance safety.','original'),
('127.888.d.2.A',4,'Hearing protection is worn during riveting because the noise can:','["clear the air", "damage hearing over time", "improve hearing", "cool the shop"]'::jsonb,1,'Noise hazard.','original'),
('127.888.d.2.B',3,'A student compares aluminum alloy skin, titanium fittings and steel fasteners and notes their strengths. She is identifying:','["no metals", "only paint", "characteristics and types of metallic structures", "only plastics"]'::jsonb,2,'Metal types.','original'),
('127.888.d.2.B',4,'Aluminum is widely used in aircraft skins mainly because it is:','["very brittle", "very soft only", "very heavy", "strong for its weight"]'::jsonb,3,'Light and strong.','original'),
('127.888.d.2.C',3,'A mechanic finds a dent, a crack and a corroded patch on a panel and picks matching sheet metal for the repair. She is identifying:','["types of sheet metal defects and selecting repair materials", "only color", "no defects", "only labels"]'::jsonb,0,'Defects and materials.','original'),
('127.888.d.2.C',4,'A repair patch for an aluminum skin should be made from:','["thinner metal", "material of the same type and at least the same thickness", "any scrap", "plastic wrap"]'::jsonb,1,'Match material.','original'),
('127.888.d.2.D',3,'A technician uses a dye penetrant and an eddy current probe to check a wing fitting for hidden cracks. She is explaining:','["guessing", "painting", "inspection and testing processes of metal structures", "cleaning only"]'::jsonb,2,'Inspection methods.','original'),
('127.888.d.2.D',4,'Dye penetrant testing is used to find:','["paint color", "fuel leaks", "internal voids only", "surface cracks in metal parts"]'::jsonb,3,'Penetrant testing.','original'),
('127.888.d.2.E',3,'A mechanic checks the manual to choose the rivet material, size and head type for a skin patch. She is explaining:','["the selection of rivets, hardware and fasteners for a sheet metal repair", "random choice", "skipping data", "using any bolt"]'::jsonb,0,'Fastener selection.','original'),
('127.888.d.2.E',4,'Using a rivet made of the wrong alloy can cause:','["better strength", "galvanic corrosion or insufficient strength", "less weight", "no effect"]'::jsonb,1,'Alloy matching.','original'),
('127.888.d.2.F',3,'A student lays out a patch, bends it on a brake and drills the holes at the spacing the approved data lists. She is explaining:','["random layout", "guesswork", "the layout, forming and drilling of sheet metal components per FAA-approved data", "unapproved methods"]'::jsonb,2,'Layout and forming.','original'),
('127.888.d.2.F',4,'The minimum distance from a rivet hole to the edge of a sheet is set by approved data to:','["reduce strength", "add weight", "cause cracks", "prevent tearing out at the edge"]'::jsonb,3,'Edge distance.','original'),
('127.888.d.2.G',3,'A student marks the rivet rows on a repair, sets each rivet and later drills out one that was set badly. She is explaining:','["rivet layout, installation and removal per FAA-approved data", "no layout", "unapproved removal", "random setting"]'::jsonb,0,'Rivet work.','original'),
('127.888.d.2.G',4,'To remove a faulty rivet without enlarging the hole, a mechanic should:','["burn it", "drill just the head and punch out the shank carefully", "hammer the skin", "pry it out"]'::jsonb,1,'Careful removal.','original'),
('127.888.d.3.A',3,'In shop class, Ben sets a universal head rivet, a countersunk rivet and a blind rivet, then drills one out. He is:','["buying rivets", "painting rivets", "installing and removing solid and blind rivets", "bending rivets"]'::jsonb,2,'Rivet types.','original'),
('127.888.d.3.A',4,'A countersunk rivet is chosen when the surface must be:','["raised", "rough", "painted", "flush with the skin"]'::jsonb,3,'Flush surface.','original'),
('127.888.d.3.B',3,'A student sketches a patch, labels the sheet metal thickness and shows how many rivets it needs. She is:','["creating a drawing of a repair, including the number of rivets and size of sheet metal", "guessing", "avoiding drawings", "ignoring sizes"]'::jsonb,0,'Repair drawing.','original'),
('127.888.d.3.B',4,'A repair drawing should show:','["a joke", "the patch size, material and rivet pattern", "only a name", "only a color"]'::jsonb,1,'Drawing details.','original'),
('127.888.d.3.C',3,'Using the manual''s spacing rules, a student plans the rows and spacing of rivets for a skin patch. She is:','["ignoring spacing", "using one rivet", "designing a rivet pattern for a specific repair", "guessing"]'::jsonb,2,'Rivet pattern.','original'),
('127.888.d.3.C',4,'Rivets in a repair are staggered or evenly spaced so the load is:','["random", "ignored", "concentrated in one spot", "spread across the patch"]'::jsonb,3,'Load distribution.','original'),
('127.888.d.3.D',3,'A mechanic checks whether a thin skin repair can be used on a stressed wing panel or only on a light fairing. She is determining:','["the applicability of sheet metal for a repair in a specific application", "random choice", "no application", "no limits"]'::jsonb,0,'Check applicability.','original'),
('127.888.d.3.D',4,'A repair meant for a non-structural fairing may not be allowed on:','["a seat cover", "a primary structural component", "a map light", "a cargo liner"]'::jsonb,1,'Structure limits.','original'),
('127.888.d.3.E',3,'A technician opens the manufacturer''s structural repair manual and builds a patch plan from its charts. She is:','["using memory", "using guesses", "designing a repair using a manufacturer''s structural repair manual", "skipping the manual"]'::jsonb,2,'Use SRM.','original'),
('127.888.d.3.E',4,'A structural repair manual is the best source for:','["seat covers", "recipes", "flight plans", "approved repair limits and procedures for that model"]'::jsonb,3,'SRM authority.','original'),
('127.888.d.3.F',3,'A student sketches a damaged area, cuts a piece of aluminum to match and forms it to fit the prepared opening. She is:','["sketching and building a piece of sheet metal to fit a prepared area", "skipping a sketch", "buying a part", "guessing"]'::jsonb,0,'Fit the patch.','original'),
('127.888.d.3.F',4,'Edges of a hand-cut patch should be filed smooth to:','["add cracks", "prevent stress cracks from starting", "increase noise", "add weight"]'::jsonb,1,'Deburr.','original'),
('127.888.d.3.G',3,'A mechanic measures a dent and a crack and decides whether the panel can be patched or must be replaced. She is:','["guessing", "painting over it", "determining the extent of damage to a metallic structure and deciding if it is repairable", "ignoring damage"]'::jsonb,2,'Assess damage.','original'),
('127.888.d.3.G',4,'If damage exceeds the limits in the repair manual, the panel should be:','["ignored", "patched anyway", "painted", "replaced or repaired with approved engineering data"]'::jsonb,3,'Beyond limits.','original'),
('127.888.d.4.A',3,'Before sanding a damaged carbon fiber panel, a technician puts on a respirator and gloves because the dust irritates lungs and skin. She is describing:','["best practices for maintenance safety related to composites", "only paint tips", "no precautions", "unsafe habits"]'::jsonb,0,'Composite safety.','original'),
('127.888.d.4.A',4,'Composite dust and resin fumes are hazards, so a shop should provide:','["no ventilation", "ventilation, respiratory protection and skin protection", "open flames", "bare hands"]'::jsonb,1,'Composite hazards.','original'),
('127.888.d.4.B',3,'A mechanic taps a wood spar, checks for rot and checks glue joints with a light and a probe. She is identifying:','["paint only", "no inspection", "tools, inspection and practices for wood structures", "metal tools only"]'::jsonb,2,'Wood inspection.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_137'
from (values
('127.888.d.4.B',4,'Dark stains and soft spots in a wooden aircraft member may indicate:','["new wood", "good glue", "fresh paint", "decay or moisture damage"]'::jsonb,3,'Wood decay.','original'),
('127.888.d.4.C',3,'A restorer reads about dope, grade A cotton, Ceconite and rib stitching on a fabric-covered wing. She is researching:','["terms used in textile (fabric) coverings", "avionics terms", "tire terms", "engine terms"]'::jsonb,0,'Fabric terms.','original'),
('127.888.d.4.C',4,'Dope applied to fabric covering is used to:','["dissolve it", "tighten and seal the fabric", "tear it", "loosen it"]'::jsonb,1,'Dope purpose.','original'),
('127.888.d.4.D',3,'A restorer attaches fabric to ribs with rib lacing and uses sewn seams and reinforcing tape. She is describing:','["random methods", "taping only", "methods of attaching textile coverings", "no methods"]'::jsonb,2,'Attachment methods.','original'),
('127.888.d.4.D',4,'Rib lacing keeps fabric from:','["staying tight", "becoming stronger", "getting wet", "lifting away from the ribs in flight"]'::jsonb,3,'Rib lacing.','original'),
('127.888.d.4.E',3,'A mechanic uses a punch tester on old fabric to see if it still has strength. She is performing:','["an inspection of textile coverings", "a tire check", "a paint job", "a weight check"]'::jsonb,0,'Fabric test.','original'),
('127.888.d.4.E',4,'Fabric that fails a strength test and tears easily must be:','["ignored", "replaced", "reused", "painted"]'::jsonb,1,'Reject weak fabric.','original'),
('127.888.d.4.F',3,'A repair plan lists scarf joints, bonded patches and bolted fasteners for a cracked composite panel. She is describing:','["paint matching", "metal bending", "composite repair methods and fasteners", "no repair"]'::jsonb,2,'Repair methods.','original'),
('127.888.d.4.F',4,'A scarf repair on a composite is made by:','["filling with putty only", "hammering", "taping over it", "tapering the damaged area and bonding a matching patch"]'::jsonb,3,'Scarf joint.','original'),
('127.888.d.4.G',3,'A student sorts fiberglass, carbon fiber and aramid fibers, honeycomb cores and epoxy matrices into groups. She is identifying:','["composite fiber, core and matrix materials", "paint types", "metal alloys", "tire rubbers"]'::jsonb,0,'Composite materials.','original'),
('127.888.d.4.G',4,'In a composite, the matrix (such as epoxy) serves to:','["fuel the part", "bind the fibers and transfer loads between them", "cool the part", "replace the fibers"]'::jsonb,1,'Matrix role.','original'),
('127.888.d.4.H',3,'A technician finds a spot where plies have separated and a dent where the honeycomb core is crushed. She is identifying:','["loose cables", "no defects", "common composite defects such as delamination and crushed core", "paint chips"]'::jsonb,2,'Composite defects.','original'),
('127.888.d.4.H',4,'Delamination is when:','["layers fuse together", "fabric tears", "paint peels", "layers of the composite separate from each other"]'::jsonb,3,'Delamination.','original'),
('127.888.d.4.I',3,'A mechanic taps along a composite skin with a coin and listens for a dull sound, then uses an ultrasonic unit. She is performing:','["inspection and testing of composites", "no inspection", "a paint job", "a tire check"]'::jsonb,0,'Composite NDT.','original'),
('127.888.d.4.I',4,'A dull sound during a tap test usually indicates:','["an overweight part", "a possible void or delamination", "new paint", "a perfect bond"]'::jsonb,1,'Dull means defect.','original'),
('127.888.d.4.J',3,'A mechanic cleans a plexiglass side window with mild soap and a soft cloth, never a harsh solvent. She is describing:','["no care", "harsh scrubbing", "window care and maintenance", "window removal"]'::jsonb,2,'Window care.','original'),
('127.888.d.4.J',4,'A dry, abrasive cloth can harm an acrylic window because it can:','["heal cracks", "strengthen it", "clean it deeply", "scratch the surface"]'::jsonb,3,'Scratches.','original'),
('127.888.d.4.K',3,'A technician learns that acrylic and polycarbonate are thermoplastics and checks them for crazing and cracks. She is covering:','["inspection and types of thermoplastics", "fabric only", "metal only", "wood only"]'::jsonb,0,'Thermoplastics.','original'),
('127.888.d.4.K',4,'Crazing in an acrylic window appears as:','["a smooth finish", "a network of fine cracks", "a clear surface", "a bright coating"]'::jsonb,1,'Crazing.','original'),
('127.888.d.4.L',3,'A mechanic uses a clear patch to stop a small crack as a temporary fix until a new window is installed. She is describing:','["wax only", "no repairs", "temporary and permanent repairs to windows", "paint only"]'::jsonb,2,'Window repairs.','original'),
('127.888.d.4.L',4,'A crack in a pressurized cabin window usually requires:','["tape forever", "nothing", "paint", "replacement rather than a simple patch"]'::jsonb,3,'Pressurized windows.','original'),
('127.888.d.4.M',3,'A mechanic checks seat belts for fraying, buckle function and worn upholstery before release. She is performing:','["an inspection of restraints and upholstery", "engine work", "painting", "no inspection"]'::jsonb,0,'Restraint check.','original'),
('127.888.d.4.M',4,'A frayed seat belt should be:','["used anyway", "removed from service and replaced", "taped", "ignored"]'::jsonb,1,'Replace frayed belts.','original'),
('127.888.d.5.A',3,'A technician checks a fiberglass wingtip, a plastic fairing and a laminated windshield for damage and plans repairs. She is:','["buying parts", "painting only", "inspecting and repairing fiberglass, composite, plastic and glass-laminated components", "avoiding repair"]'::jsonb,2,'Inspect and repair.','original'),
('127.888.d.5.A',4,'Repair of laminated glass components must follow:','["rumors", "any glue", "guesswork", "manufacturer-approved procedures"]'::jsonb,3,'Approved procedures.','original'),
('127.888.d.5.B',3,'A student cleans an acrylic windshield with water and soft cloth, then checks for crazing and scratches. She is:','["cleaning and inspecting acrylic windshields", "scrubbing with solvent", "skipping inspection", "painting it"]'::jsonb,0,'Windshield care.','original'),
('127.888.d.5.B',4,'Acrylic windshields should not be cleaned with:','["clean water", "strong solvents such as acetone", "mild soap", "a soft cloth"]'::jsonb,1,'Avoid solvents.','original'),
('127.888.d.5.C',3,'A mechanic taps a composite panel with a coin and listens for changes in the sound. She is performing:','["a pressure test", "a leak test", "a tap test on a composite", "a fuel test"]'::jsonb,2,'Tap test.','original'),
('127.888.d.5.C',4,'A tap test is most useful for finding:','["tire wear", "engine noise", "fuel leaks", "bond line problems such as delaminations"]'::jsonb,3,'Tap test use.','original'),
('127.888.d.5.D',3,'A bolt hole in a composite has become oval from wear, and the manual describes how to repair it. She is following:','["repair procedures for elongated bolt holes", "no procedure", "a guess", "a shortcut"]'::jsonb,0,'Elongated holes.','original'),
('127.888.d.5.D',4,'An elongated bolt hole in a structure is a problem because it:','["improves fit", "lets the fastener move and weaken the joint", "reduces wear", "adds strength"]'::jsonb,1,'Slop in joint.','original'),
('127.888.d.5.E',3,'A student lays plies in a mold and places the bagging film and bleeder before applying vacuum. She is:','["cutting metal", "painting a part", "performing a composite lay-up, including preparation for vacuum bagging", "welding steel"]'::jsonb,2,'Lay-up and bagging.','original'),
('127.888.d.5.E',4,'The vacuum in bagging helps by:','["adding air", "loosening plies", "adding heat only", "compressing the plies and removing air and extra resin"]'::jsonb,3,'Vacuum role.','original'),
('127.888.d.6.A',3,'A mechanic checks a flight control cable for broken wires, rust and kinks during an inspection. She is describing:','["types of control cables and their maintenance", "tire care", "paint only", "no maintenance"]'::jsonb,0,'Cable care.','original'),
('127.888.d.6.A',4,'Broken strands in a control cable should be:','["taped", "counted against the manual''s limits and replaced if exceeded", "ignored", "painted"]'::jsonb,1,'Cable limits.','original'),
('127.888.d.6.B',3,'A mechanic checks the turnbuckles, pulleys, fairleads and travel stops on a cable run. She is inspecting:','["paint", "engines", "cable connectors, guides and stops", "tires"]'::jsonb,2,'Cable hardware.','original'),
('127.888.d.6.B',4,'A fairlead is used to:','["paint the cable", "cut the cable", "pull the cable", "guide a cable and keep it from rubbing"]'::jsonb,3,'Fairlead.','original'),
('127.888.d.6.C',3,'A mechanic checks a push-pull tube and a torque tube for corrosion and bent ends. She is inspecting:','["push-pull tubes and torque tubes", "tires only", "cables only", "pulleys only"]'::jsonb,0,'Push-pull tubes.','original'),
('127.888.d.6.C',4,'A push-pull tube transmits motion by:','["burning", "pushing and pulling along its length", "twisting only", "stretching"]'::jsonb,1,'Push-pull.','original'),
('127.888.d.6.D',3,'A mechanic checks a bellcrank pivot for play and smooth movement. She is inspecting:','["paint", "wings only", "bellcranks in a control system", "tires"]'::jsonb,2,'Bellcrank.','original'),
('127.888.d.6.D',4,'A bellcrank is used to:','["hold paint", "spin a prop", "add fuel", "change the direction of motion in a control linkage"]'::jsonb,3,'Bellcrank use.','original'),
('127.888.d.6.E',3,'A shop schedules its cable tension meters for periodic calibration so the readings stay accurate. She is describing:','["the calibration schedule for cable tension meters", "once a decade", "random schedule", "no schedule"]'::jsonb,0,'Calibration.','original'),
('127.888.d.6.E',4,'An uncalibrated tension meter could cause:','["less cable", "wrong cable tension settings", "perfect tension", "no settings"]'::jsonb,1,'Bad readings.','original'),
('127.888.d.6.F',3,'A mechanic wraps a tensiometer around a cable, reads the dial and looks up the right tension on the chart for the cable size. She is:','["guessing", "using a ruler", "using a cable tensiometer and tension chart", "skipping a chart"]'::jsonb,2,'Tensiometer.','original'),
('127.888.d.6.F',4,'Cable tension charts account for the cable size and:','["the paint color", "the pilot''s weight", "the seat type", "the temperature at the time of the check"]'::jsonb,3,'Temperature correction.','original'),
('127.888.d.6.G',3,'A technician learns that a control surface that is out of balance can start to flutter in flight. She is describing:','["flutter and balance of flight controls", "tire balance", "engine balance", "no flutter"]'::jsonb,0,'Flutter.','original'),
('127.888.d.6.G',4,'Adding paint or repair material to a control surface can:','["improve balance always", "upset its balance and increase flutter risk", "lower weight", "do nothing"]'::jsonb,1,'Rebalance after repair.','original'),
('127.888.d.6.H',3,'A student names the ailerons, elevator and rudder as primary controls, and the stabilizers as fixed or adjustable surfaces. She is identifying:','["secondary controls only", "engines", "primary flight controls and stabilizers", "tires"]'::jsonb,2,'Primary controls.','original'),
('127.888.d.6.H',4,'The primary flight controls move the aircraft about its:','["engine axes", "fuel axes", "tire axes", "pitch, roll and yaw axes"]'::jsonb,3,'Three axes.','original'),
('127.888.d.6.I',3,'A student lists flaps, slats, spoilers and trim tabs as controls that help with lift, drag or balance. She is identifying:','["secondary or auxiliary control surfaces", "primary controls", "engines", "tires"]'::jsonb,0,'Secondary controls.','original'),
('127.888.d.6.I',4,'Flaps are lowered during landing to:','["stop engines", "increase lift at lower speeds", "reduce lift", "increase speed"]'::jsonb,1,'Flaps.','original'),
